from robot.utils.robottime import timestr_to_secs
from ute_common_store import Store
from ute_common_converter.to_number import to_float, to_int
from ute_common_converter.to_bool import to_bool
from ute_common_bts.fsm import FsmServices

from ute_fsmaccess.manager import SSHConnectionManager
from ute_fsmaccess.enbaccess import EnbFsmAccess
from ute_fsmaccess.interface.common import FsmCommonInterface
from ute_fsmaccess.exception import FileDoNotExist, DictionaryDoNotExist


class EnbFsmInterface(FsmCommonInterface):

    def __init__(self):
        super(EnbFsmInterface, self).__init__()
        self.enb_store = Store()
        self.ssh_forwarder = None
        self.env = 'fsmf'

    def setup_enb_fsm_access(self, host='192.168.255.1', user='toor4nsn', password='oZPS0POrRieRtu', port=22, timeout=20.0, prompt=' >',
                             trs_ip='192.168.255.129', remote_host=None, retry_timeout=60.0, env='fsmf', fallback_prompt=None,
                             private_key=None, **kwargs):
        """ Prepare Ssh Connection to eNB Fsm.

        :param string host:             Ip address or domain name of Enb Fsm.
                                        If no value is given, the library will scan for available ENB IP address.
        :param string user:             SSH login.
        :param string password:         SSH password.
        :param integer port:            SSH port.
        :param float timeout:           Timeout for SSH execution commands.
        :param string prompt:           Enb Fsm console prompt.
        :param string remote_host:      Ip address or domain name of remote host.
        :param float retry_timeout:     Timeout for retrying SSH login.
        :param string fallback_prompt:  Client will attempt to use this if 'prompt' fails. As consequence, timeout duration will double.
                                        The default value of 'None' will not trigger this behavior.
        :param string private_key:      If provided, Log in to the host using the provided private key. Default is 'None'.

        |
        :Full support for root user is available via kwargs:
            * **root_username** (string)   - Username for root authentication. Default is 'toor4nsn'.
            * **root_password** (string)   - Password for root authentication. Default is 'oZPS0POrRieRtu'
            * **root_private_key** (string) - Location (absolute path) of custom service private key (id_rsa)

        :Full support for remote host is available via kwargs:
            * **remote_ssh_user** (string)   - Username for remote host authentication. Default is 'ute'.
            * **remote_ssh_pass** (string)   - Password for remote host authentication. Default is 'ute'.
            * **remote_ssh_prompt** (string) - SSH prompt received after logging in remote host. Default is '$ '.

        :Other arguments available via kwargs:
            * **trs_user** (string)  - Transport username. Default is 'Nemuadmin'.
            * **trs_pass** (string)  - Transport password. Default is 'nemuuser'.

        .. note:: When LTE2647 is enabled, you need to explicitly provide 'serviceuser' credentials. You need to provide\
 'root_private_key' for root access:
        .. code-block:: python

            Setup Enb Fsm Access    user=serviceuser    password=<service password>     private_key=/path/to/id_rsa    \
root_private_key=/path/to/id_rsa
        """
        port = to_int(port)
        timeout = to_float(timeout)
        retry_timeout = to_float(retry_timeout)
        self.env = env
        fsm_service_params = {'trs_ip': trs_ip, 'trs_user': kwargs.get('trs_user', 'Nemuadmin'),
                              'trs_pass': kwargs.get('trs_pass', 'nemuuser'), 'timeout': timeout}
        remote_host_params = {'remote_host': remote_host, 'remote_ssh_user': kwargs.get('remote_ssh_user', 'ute'),
                              'remote_ssh_pass': kwargs.get('remote_ssh_pass', 'ute'), 'remote_ssh_prompt': kwargs.get('remote_ssh_prompt', '$ ')}
        manager = SSHConnectionManager(host, user, password, port, timeout, prompt, remote_host, retry_timeout,
                                       fallback_prompt, private_key, **kwargs)
        fsm_service_params.update(remote_host_params)
        self.enb_store.add(EnbFsmAccess(manager, fsm_services=FsmServices(**fsm_service_params)),
                           alias=kwargs.get('alias'))

    def teardown_enb_fsm_access(self, **kwargs):
        """ Close SSH session and cleanup connection.
        """
        self.enb_store.remove(alias=kwargs.get('alias'))

    def teardown_all_aliases_for_enb_fsmaccess(self):
        """ Calls teardown_enb_fsm_access on each alias in enb_store
        """
        for alias_name in self.enb_store.aliases:
            self.teardown_enb_fsm_access(alias=alias_name)

    def get_enb_scfc_file(self, destination, partition='active', **kwargs):
        """Copy SCFC.xml from defined partition of eNB to specified localization on PC.

        :param string destination:     Destination directory path.
        :param string partition:       Partition type, default: active.

        :return:                        Destination path.
        :rtype:                         string
        """
        source, destination = self.enb_store.get(alias=kwargs.get('alias')).get_enb_scfc(dst=destination, partition=partition, env=self.env)
        return destination

    def put_enb_scfc_file(self, source, partition='active', ignore_multiple_scfc=False, **kwargs):
        """Copy SCFC.xml from specified localization to defined partition of eNB.

        :param string source:          Source file path.
        :param string partition:       Partition type, default: active.

        :return:                        Source path.
        :rtype:                         string
        """
        source, destination = self.enb_store.get(alias=kwargs.get('alias')).put_enb_scfc(src=source, partition=partition,
                                                                                         env=self.env, ignore_multiple_scfc=ignore_multiple_scfc)
        return source

