    def get_enb_sw_version(self, partition='active', **kwargs):
        """Get eNB software version.

        :param string partition:        Partition type, default: active.

        :return:                        Enb software version.
        :rtype:                         string
        """
        return self.enb_store.get(alias=kwargs.get('alias')).get_fsm_sw_version(partition)

    def get_enb_hw_version(self, **kwargs):
        """Get eNB hardware version.

        :return:         eNB hardware version.
        :rtype:          string
        """
        return self.enb_store.get(alias=kwargs.get('alias')).get_fsm_hw_version()

    def file_should_exist_on_enb(self, file_path, **kwargs):
        """ Fails if given file does not exist on eNB.

        :param string source:          Path to file.
        """
        if not (self.enb_store.get(alias=kwargs.get('alias')).file_exists(file_path)):
            raise FileDoNotExist('File %s DOES NOT exist' % file_path)

    def dir_should_exist_on_enb(self, dir_path, **kwargs):
        """ Fails if given file directory does not exist on eNB.

        :param string source:          Path to directory.
        """
        if not (self.enb_store.get(alias=kwargs.get('alias')).dir_exists(dir_path)):
            raise DictionaryDoNotExist('Dictionary %s DOES NOT exist' % dir_path)

    def file_exists_on_enb(self, file_path, **kwargs):
        """Check if given file exists on Fsm.

        :param string file_path:        File path.

        :return:                        True/False.
        :rtype:                         bool

        """
        return to_bool(self.enb_store.get(alias=kwargs.get('alias')).file_exists(file_path))

    def dir_exists_on_enb(self, dir_path, **kwargs):
        """Check if given dictionary exists on Fsm.

        :param string dir_path:        Dictionary path.

        :return:                        True/False.
        :rtype:                         bool

        """
        return to_bool(self.enb_store.get(alias=kwargs.get('alias')).dir_exists(dir_path))

    def get_enb_file(self, source, destination, **kwargs):
        """Copy a file from source on eNB to destination on the local machine.

        :param string source:         Source file path.
        :param string destination:    Destination directory path.

        :return:                     Destination path.
        :rtype:                      string
        """
        source, destination = self.enb_store.get(alias=kwargs.get('alias')).get_fsm_file(src=source, dst=destination)
        return destination

    def get_enb_directory(self, source, tar_output, **kwargs):
        """Copy a directory from source on eNB to destination on the local machine

        :param source:          Source file directory
        :param tar_output:      Destination output tarfile

        :return tar_output:     Destination output tarfile
        :rtype: string
        :raises: ValueError for invalid filename extension

        :note: These examples will produce the following results for tar_output:
            * filename.tar.bz2 (already has '.tar.bz2' extension)
            * some_filename (will append '.tar.bz2' extension)
            * some_filename.zip (will raise ValueError)
        """
        return self.enb_store.get(alias=kwargs.get('alias')).get_fsm_directory(src=source, tar_output=tar_output)

    def put_enb_file(self, source, destination, partition='active', **kwargs):
        """Copy a file from source on the local machine to destination on eNB.

        :param string source:         Source file path.
        :param string destination:    Destination file path.

        :return:                     Source file path.
        :rtype:                      string
        """
        source, destination = self.enb_store.get(alias=kwargs.get('alias')).put_fsm_file(src=source, dst=destination, partition=partition)
        return source

    def execute_command_on_enb(self, cmd, return_rc=False, **kwargs):
        """ Execute shell command on eNB.

        :param string cmd:           Shell command to be executed.
        :param bool   return_rc:     Flag for returning shell command rc. Default: False.

        :return:                     Shell command output. If return_rc is True, also returns shell command rc.
        :rtype:                      string or (string, int)
        """
        return self.enb_store.get(alias=kwargs.get('alias')).execute(cmd, return_rc)

    def start_command_on_enb(self, cmd, **kwargs):
        """ Start shell command on eNB. Unlike to "execute command", "start command" does not
        wait for return code

        :param string cmd:      Shell command to be started.

        """
        self.enb_store.get(alias=kwargs.get('alias')).start_command(cmd)

    def get_partition_path(self, partition, **kwargs):
        """Get eNB partition path.

        :param string partition:        Partition type.

        :return:                        Partition path.
        :rtype:                         String
        """
        return self.enb_store.get(alias=kwargs.get('alias')).get_partition_path(partition)

    def get_enb_partition_path(self, partition, **kwargs):
        """Get eNB partition path.

        :param string partition:        Partition type.

        :return:                        Partition path.
        :rtype:                         String
        """
        return self.enb_store.get(alias=kwargs.get('alias')).get_partition_path(partition)

    def enable_enb_ssh(self, timeout='5min', **kwargs):
        """Enable SSH services on FSM.

        :param String  timeout:        Timeout in enabling SSH. Default is 5min.
        """
        timeout = timestr_to_secs(timeout)
        return self.enb_store.get(alias=kwargs.get('alias')).enable_ssh(timeout=timeout)

    def enable_enb_rnd_ports(self, **kwargs):
        """Enable RND services on FSM."""

        return self.enb_store.get(alias=kwargs.get('alias')).enable_rnd_ports()

    def remove_trs_configuration(self, **kwargs):
        """Remove trs configuration."""

        return self.enb_store.get(alias=kwargs.get('alias')).remove_trs_configuration()

    def set_writeable_enb_passive_partition(self, **kwargs):
        """Set read-write permission mode for eNB passive partition."""

        self.enb_store.get(alias=kwargs.get('alias')).set_writeable_enb_passive_partition()
